113	// Keep the broker's original descriptor until all private renderer/notifier
114	// duplicates are retired. Dropping an OwnedFd alone does not call Session::close.
115	struct SeatDevice<S: Session + Clone> {
116	    fd: Option<OwnedFd>,
117	    session: S,
118	    close_failures: Rc<Cell<u64>>,
119	    _owner: Option<Rc<dyn Any>>,
120	}
121	impl<S: Session + Clone> SeatDevice<S> {
122	    fn open(mut session: S, path: &Path, close_failures: Rc<Cell<u64>>) -> Result<Self, Failure> {
123	        if !session.is_active() {
124	            return Err(Failure::at(Stage::Inactive));
125	        }
126	        let fd = session
127	            .open(
128	                path,
129	                OFlags::RDWR | OFlags::CLOEXEC | OFlags::NONBLOCK | OFlags::NOCTTY,
130	            )
131	            .map_err(|e| Failure {
132	                stage: Stage::DeviceOpen,
133	                errno: e.as_errno(),
134	            })?;
135	        let device = Self {
136	            fd: Some(fd),
137	            session,
138	            close_failures,
139	            _owner: None,
140	        };
141	        enforce_flags(device.fd.as_ref().expect("owned descriptor")).map_err(|e| Failure {
142	            stage: Stage::DeviceFlags,
143	            errno: e.raw_os_error(),
144	        })?;
145	        Ok(device)
146	    }
147	    fn duplicate(&self) -> Result<OwnedFd, Failure> {
148	        self.fd
149	            .as_ref()
150	            .expect("owned descriptor")
151	            .try_clone()
152	            .map_err(|e| Failure {
153	                stage: Stage::DeviceDuplicate,
154	                errno: e.raw_os_error(),
155	            })
156	    }
157	}
158	fn enforce_flags(fd: &OwnedFd) -> std::io::Result<()> {
159	    let raw = fd.as_raw_fd();
160	    // SAFETY: the private live OwnedFd remains borrowed throughout these calls.
161	    unsafe {
162	        let flags = libc::fcntl(raw, libc::F_GETFD);
163	        if flags < 0 {
164	            return Err(std::io::Error::last_os_error());
165	        }
166	        let status = libc::fcntl(raw, libc::F_GETFL);
167	        if status < 0 {
168	            return Err(std::io::Error::last_os_error());
169	        }
170	        if libc::fcntl(raw, libc::F_SETFD, flags | libc::FD_CLOEXEC) != 0
171	            || libc::fcntl(raw, libc::F_SETFL, status | libc::O_NONBLOCK) != 0
172	        {
173	            return Err(std::io::Error::last_os_error());
174	        }
175	        let fd_flags = libc::fcntl(raw, libc::F_GETFD);
176	        let status_flags = libc::fcntl(raw, libc::F_GETFL);
177	        if fd_flags < 0 || status_flags < 0 {
178	            return Err(std::io::Error::last_os_error());
179	        }
180	        if fd_flags & libc::FD_CLOEXEC == 0 || status_flags & libc::O_NONBLOCK == 0 {
181	            return Err(std::io::Error::from_raw_os_error(libc::EIO));
182	        }
183	    }
184	    Ok(())
185	}
