245	fn pin_lease<L, E, M, D, R>(
246	    lease: L,
247	    mut callback: impl FnMut(E, &mut M, &mut D) -> R,
248	) -> impl FnMut(E, &mut M, &mut D) -> R {
249	    move |event, metadata, data| {
250	        let _lease = &lease;
251	        callback(event, metadata, data)
252	    }
253	}
