298	/// Sources capture weak ownership. The independent session dispatcher outlives
299	/// input/GPU cleanup, including errors during partial initialization.
300	pub struct Driver<D: 'static> {
301	    kernel: Rc<RefCell<Kernel<D>>>,
302	    tokens: Vec<Registration>,
303	    _session_owner: Rc<Dispatcher<'static, LibSeatSessionNotifier, D>>,
304	}
305	impl<D: 'static> Driver<D> {
306	    pub fn new(
307	        handle: &LoopHandle<'static, D>,
308	        data: &mut D,
309	        notify: impl Fn(NativeEvent, &mut D) + 'static,
310	    ) -> Result<Self, Failure> {
311	        let (session, notifier) = LibSeatSession::new().map_err(|e| Failure {
312	            stage: Stage::SeatOpen,
313	            errno: e.as_errno(),
314	        })?;
315	        let notify: Notify<D> = Rc::new(notify);
316	        let weak_loop = handle.downgrade();
317	        let weak_handle: WeakHandle<D> = Rc::new(move || weak_loop.upgrade());
318	        let kernel = Rc::new(RefCell::new(Kernel {
319	            model: Lifecycle::default(),
320	            session: session.clone(),
321	            paths: BTreeMap::new(),
322	            gpus: BTreeMap::new(),
323	            input: None,
324	            input_token: None,
325	            handle: weak_handle.clone(),
326	            notify: notify.clone(),
327	            close_failures: Rc::new(Cell::new(0)),
328	            seat_owner: None,
329	        }));
330	        let weak = Rc::downgrade(&kernel);
331	        let owner = Rc::new(Dispatcher::new(notifier, move |event, _, data: &mut D| {
332	            let Some(kernel) = weak.upgrade() else { return };
333	            let events = match event {
334	                SessionEvent::PauseSession => kernel.borrow_mut().pause(),
335	                SessionEvent::ActivateSession => {
336	                    kernel.borrow_mut().activate(&Rc::downgrade(&kernel))
337	                }
338	            };
339	            let notify = kernel.borrow().notify.clone();
340	            dispatch_events(
341	                events,
342	                |event| notify(event, data),
343	                || !kernel.borrow().model.closed(),
344	            );
345	        }));
346	        kernel.borrow_mut().seat_owner = Some(owner.clone());
347	        let mut driver = Self {
348	            kernel,
349	            tokens: vec![],
350	            _session_owner: owner,
351	        };
352	        let token = handle
353	            .register_dispatcher((*driver._session_owner).clone())
354	            .map_err(|_| Failure::at(Stage::SourceRegistration))?;
355	        driver
356	            .tokens
357	            .push(Registration::new(weak_handle.clone(), token));
358	        let udev = UdevBackend::new(session.seat()).map_err(|e| Failure {
359	            stage: Stage::UdevMonitor,
360	            errno: e.raw_os_error(),
361	        })?;
362	        let initial: Vec<_> = udev
363	            .device_list()
364	            .map(|(id, path)| UdevEvent::Added {
365	                device_id: id,
366	                path: path.to_owned(),
367	            })
368	            .collect();
369	        let weak = Rc::downgrade(&driver.kernel);
370	        let token = handle
371	            .insert_source(udev, move |event, _, data| {
372	                let Some(kernel) = weak.upgrade() else { return };
373	                let events = kernel.borrow_mut().udev(event, &Rc::downgrade(&kernel));
374	                let notify = kernel.borrow().notify.clone();
375	                dispatch_events(
376	                    events,
377	                    |event| notify(event, data),
378	                    || !kernel.borrow().model.closed(),
379	                );
380	            })
381	            .map_err(|_| Failure::at(Stage::SourceRegistration))?;
382	        driver
383	            .tokens
384	            .push(Registration::new(weak_handle.clone(), token));
385	        for event in initial {
386	            let events = driver
387	                .kernel
388	                .borrow_mut()
389	                .udev(event, &Rc::downgrade(&driver.kernel));
390	            for event in events {
391	                notify(event, data);
392	            }
393	        }
394	        if session.is_active() {
395	            let events = driver
396	                .kernel
397	                .borrow_mut()
398	                .activate(&Rc::downgrade(&driver.kernel));
399	            for event in events {
400	                notify(event, data);
401	            }
402	        }
403	        Ok(driver)
404	    }
