430	// Stop a precomputed batch if a notification synchronously shuts down its owner.
431	// Deliver the first item even if initialization sealed admission, so failures
432	// remain observable; never deliver later ready events after stop/drop.
433	fn dispatch_events<E>(
434	    events: impl IntoIterator<Item = E>,
435	    mut notify: impl FnMut(E),
436	    live: impl Fn() -> bool,
437	) {
438	    for event in events {
439	        notify(event);
440	        if !live() {
441	            break;
442	        }
443	    }
444	}
445	// Apply the pause before any fields retire. This suppresses Smithay's implicit
446	// active-device KMS restore on Changed/Removed/stop; no surfaces exist yet.
447	fn retire_paused<T>(resource: Option<T>, pause: impl FnOnce(&mut T)) {
448	    if let Some(mut resource) = resource {
449	        pause(&mut resource);
450	    }
451	}
452	impl<D: 'static> Kernel<D> {
453	    fn failure(device: Option<u64>, stage: Stage) -> NativeEvent {
454	        NativeEvent::Failure {
455	            device,
456	            error: Failure::at(stage),
457	        }
458	    }
459	    fn retire(&mut self, id: u64) {
460	        // Hotplug must not restore a connector snapshot captured before change.
461	        retire_paused(self.gpus.remove(&id), |gpu| gpu.drm.pause());
462	    }
463	    fn stop(&mut self) {
464	        self.model.stop();
465	        if let Some(input) = &mut self.input {
466	            input.suspend();
467	        }
468	        self.input_token.take();
469	        self.input.take();
470	        let devices: Vec<_> = self.gpus.keys().copied().collect();
471	        for id in devices {
472	            self.retire(id);
473	        }
474	        self.paths.clear();
475	    }
476	    fn pause(&mut self) -> Vec<NativeEvent> {
477	        match self.model.pause() {
478	            Ok(false) => vec![],
479	            Ok(true) => {
480	                if let Some(input) = &mut self.input {
481	                    input.suspend();
482	                }
483	                for gpu in self.gpus.values_mut() {
484	                    gpu.drm.pause();
485	                }
486	                vec![NativeEvent::SessionActive(false)]
487	            }
488	            Err(_) => {
489	                self.stop();
490	                vec![
491	                    Self::failure(None, Stage::Lifecycle),
492	                    NativeEvent::SessionActive(false),
493	                ]
494	            }
